using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests
{
    [Fact]
    public async Task Sends_the_reference_amount_and_currency_the_provider_expects()
    {
        var handler = new StubHttpMessageHandler((request, body) =>
            new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = JsonContent("""{"status":"approved"}""")
            });
        var gateway = new HttpPaymentGateway(CreateClient(handler));

        await gateway.AuthorizeAsync("ORD-1", new Money(42.50m, "eur"), CancellationToken.None);

        Assert.Equal(HttpMethod.Post, handler.LastRequest!.Method);
        Assert.Equal("/v1/authorizations", handler.LastRequest.RequestUri!.AbsolutePath);

        using var payload = JsonDocument.Parse(handler.LastRequestBody!);
        var root = payload.RootElement;
        Assert.Equal("ORD-1", root.GetProperty("reference").GetString());
        Assert.Equal(42.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task A_200_response_of_approved_is_read_back_as_approved()
    {
        var handler = new StubHttpMessageHandler((request, body) =>
            new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = JsonContent("""{"status":"approved"}""")
            });
        var gateway = new HttpPaymentGateway(CreateClient(handler));

        var outcome = await gateway.AuthorizeAsync("ORD-1", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_200_response_of_declined_is_read_back_as_declined()
    {
        var handler = new StubHttpMessageHandler((request, body) =>
            new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = JsonContent("""{"status":"declined"}""")
            });
        var gateway = new HttpPaymentGateway(CreateClient(handler));

        var outcome = await gateway.AuthorizeAsync("ORD-2", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_response_means_the_provider_refused_the_payment_outright()
    {
        var handler = new StubHttpMessageHandler((request, body) =>
            new HttpResponseMessage(HttpStatusCode.PaymentRequired));
        var gateway = new HttpPaymentGateway(CreateClient(handler));

        var outcome = await gateway.AuthorizeAsync("ORD-3", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unrecognised_status_value_is_treated_as_declined()
    {
        var handler = new StubHttpMessageHandler((request, body) =>
            new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = JsonContent("""{"status":"pending_review"}""")
            });
        var gateway = new HttpPaymentGateway(CreateClient(handler));

        var outcome = await gateway.AuthorizeAsync("ORD-4", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_empty_body_on_a_200_is_treated_as_declined()
    {
        var handler = new StubHttpMessageHandler((request, body) =>
            new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent(string.Empty)
            });
        var gateway = new HttpPaymentGateway(CreateClient(handler));

        var outcome = await gateway.AuthorizeAsync("ORD-5", new Money(10m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(HttpStatusCode.BadRequest)]
    [InlineData(HttpStatusCode.Unauthorized)]
    [InlineData(HttpStatusCode.InternalServerError)]
    [InlineData(HttpStatusCode.ServiceUnavailable)]
    public async Task Any_other_failing_status_bubbles_up_as_an_exception(HttpStatusCode statusCode)
    {
        var handler = new StubHttpMessageHandler((request, body) => new HttpResponseMessage(statusCode));
        var gateway = new HttpPaymentGateway(CreateClient(handler));

        await Assert.ThrowsAsync<HttpRequestException>(
            () => gateway.AuthorizeAsync("ORD-6", new Money(10m, "EUR"), CancellationToken.None));
    }

    [Fact]
    public async Task Malformed_json_on_a_200_response_bubbles_up_as_an_exception()
    {
        var handler = new StubHttpMessageHandler((request, body) =>
            new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent("{not-json", Encoding.UTF8, "application/json")
            });
        var gateway = new HttpPaymentGateway(CreateClient(handler));

        await Assert.ThrowsAsync<JsonException>(
            () => gateway.AuthorizeAsync("ORD-7", new Money(10m, "EUR"), CancellationToken.None));
    }

    private static HttpClient CreateClient(HttpMessageHandler handler) =>
        new(handler) { BaseAddress = new Uri("https://provider.example") };

    private static StringContent JsonContent(string json) => new(json, Encoding.UTF8, "application/json");

    private sealed class StubHttpMessageHandler(Func<HttpRequestMessage, string?, HttpResponseMessage> respond) : HttpMessageHandler
    {
        public HttpRequestMessage? LastRequest { get; private set; }

        public string? LastRequestBody { get; private set; }

        protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
        {
            LastRequest = request;
            LastRequestBody = request.Content is null ? null : await request.Content.ReadAsStringAsync(cancellationToken);
            return respond(request, LastRequestBody);
        }
    }
}
EOF
